from datetime import datetime
from typing import List, Optional
from pydantic import BaseModel, ConfigDict, Field, computed_field

from app.models.enums import (
    PracticeItemReviewAction,
    PracticeItemReviewStatus,
    PracticeQuestionType,
    RemediationRunStatus,
)


class PracticeItemOutput(BaseModel):
    """Structured output generated by a remediation generator."""
    target_concept: Optional[str] = None
    question_text: str = Field(..., min_length=5, description="Student-facing practice prompt (never reveals expected answer)")
    question_type: PracticeQuestionType = Field(default=PracticeQuestionType.SHORT_ANSWER)
    options: Optional[List[str]] = Field(None, description="Options for multiple choice practice questions")
    teacher_answer_key: Optional[str] = Field(None, description="Teacher-only reference answer key")
    teacher_rationale: Optional[str] = Field(None, description="Teacher-only pedagogical rationale")
    difficulty: Optional[str] = Field("medium", description="Estimated difficulty (easy, medium, hard)")
    uncertainty_note: Optional[str] = Field(None, description="Uncertainty or limitation notes regarding generation")


class RemediationItemAuditRead(BaseModel):
    id: int
    item_id: int
    reviewer_id: int
    action: PracticeItemReviewAction
    previous_status: Optional[str] = None
    new_status: str
    edited_question_text: Optional[str] = None
    edited_answer_key: Optional[str] = None
    review_notes: Optional[str] = None
    created_at: datetime

    model_config = ConfigDict(from_attributes=True)


class RemediationItemTeacherRead(BaseModel):
    """Detailed practice item view for teachers, including answer key and rationale."""
    id: int
    run_id: int
    finding_id: int
    target_concept: Optional[str] = None
    question_text: str
    question_type: PracticeQuestionType
    options: Optional[List[str]] = None
    teacher_answer_key: Optional[str] = None
    teacher_rationale: Optional[str] = None
    difficulty: Optional[str] = None
    uncertainty_note: Optional[str] = None
    review_status: PracticeItemReviewStatus
    edited_question_text: Optional[str] = None
    edited_answer_key: Optional[str] = None
    reviewed_by: Optional[int] = None
    reviewed_at: Optional[datetime] = None
    review_notes: Optional[str] = None
    created_at: datetime
    updated_at: datetime

    @computed_field
    @property
    def effective_question_text(self) -> str:
        """Returns edited question text if provided by teacher, otherwise original generated prompt."""
        return self.edited_question_text or self.question_text

    @computed_field
    @property
    def effective_answer_key(self) -> Optional[str]:
        """Returns edited answer key if provided by teacher, otherwise original generated key."""
        return self.edited_answer_key or self.teacher_answer_key

    model_config = ConfigDict(from_attributes=True)


class RemediationItemStudentRead(BaseModel):
    """
    Student-facing practice item view.
    CRITICAL: Never exposes teacher_answer_key, teacher_rationale, or teacher review notes.
    """
    id: int
    finding_id: int
    target_concept: Optional[str] = None
    question_text: str
    question_type: PracticeQuestionType
    options: Optional[List[str]] = None
    difficulty: Optional[str] = None

    model_config = ConfigDict(from_attributes=True)


class RemediationRunRead(BaseModel):
    id: int
    finding_id: int
    evaluation_run_id: int
    generator_name: str
    status: RemediationRunStatus
    error_message: Optional[str] = None
    created_at: datetime
    updated_at: datetime

    model_config = ConfigDict(from_attributes=True)


class RemediationRunDetailRead(RemediationRunRead):
    items: List[RemediationItemTeacherRead] = []


class PracticeItemReviewRequest(BaseModel):
    action: PracticeItemReviewAction = Field(..., description="Review action: approve, reject, or edit")
    edited_question_text: Optional[str] = Field(None, max_length=2000, description="Teacher-edited student prompt (required if action is edit)")
    edited_answer_key: Optional[str] = Field(None, max_length=1000, description="Teacher-edited answer key")
    review_notes: Optional[str] = Field(None, max_length=1000, description="Pedagogical notes on review/edits")


class PracticeItemReviewResponse(BaseModel):
    item: RemediationItemTeacherRead
    audit: RemediationItemAuditRead


class RemediationGenerationSummary(BaseModel):
    finding_id: int
    run_id: int
    status: RemediationRunStatus
    items_count: int
    items: List[RemediationItemTeacherRead]
